input.content:
"use server"

import { revalidatePath } from "next/cache"

let notificationEnabled = false

export async function getNotificationPreference() {
  return notificationEnabled
}

export async function toggleNotification() {
  notificationEnabled = !notificationEnabled
  revalidatePath("/")
}

import { getNotificationPreference, toggleNotification } from "./actions"

export default async function Home() {
  const enabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications: {enabled ? "On" : "Off"}</p>
      <form action={toggleNotification}>
        <button type="submit">
          {enabled ? "Turn Off Notifications" : "Turn On Notifications"}
        </button>
      </form>
    </main>
  )
}

